INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (3000, 2, "調子が上がって\nきたなっ", 2, "vo_minigame_1013_icon_2_002_001", 1, 1000, 2, "vo_minigame_1013_icon_1_002_001", "訓練はまだ\nここからですわ");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (3000, 2, "ほらほら、\nまだいけるだろ？", 2, "vo_minigame_1013_icon_2_003_001", 2, 5000, 2, "vo_minigame_1013_icon_1_003_001", "クスクス、悪くない\n流れですわね");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (3000, 2, "へへっ、おまえら\nやるじゃねえか！", 3, "vo_minigame_1013_icon_2_004_001", 3, 10000, 2, "vo_minigame_1013_icon_1_004_001", "すばらしい\n記録ですわ");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (3000, 2, "あたしたちはまだ\n止まらねえぜ！", 3, "vo_minigame_1013_icon_2_005_001", 4, 10000, 3, "vo_minigame_1013_icon_1_005_001", "乗りに乗って\nいますわね");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (3000, 2, "見てろよ！\nマコト班の快進撃だ！", 3, "vo_minigame_1013_icon_2_005_002", 5, 10000, 3, "vo_minigame_1013_icon_1_005_002", "まだまだ行きます\nついてきなさい");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (3000, 2, "うおぉぉっ！\n絶好調だぜ！", 3, "vo_minigame_1013_icon_2_005_003", 6, 10000, 3, "vo_minigame_1013_icon_1_005_003", "エリコ班の\n本領発揮ですわ！");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (3000, 2, "どこまで行けるか\n楽しみだなっ！", 3, "vo_minigame_1013_icon_2_006_001", 7, 0, 4, "vo_minigame_1013_icon_1_006_001", "ここからは\n前人未到の領域です！");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (1000, 3, "まだ諦めんなよっ", 4, "vo_minigame_1013_icon_2_007_001", 8, 1, 5, "vo_minigame_1013_icon_1_007_001", "厄介でしたわ…");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (1000, 3, "冷やっとしたぜ…！", 4, "vo_minigame_1013_icon_2_007_002", 9, 1, 5, "vo_minigame_1013_icon_1_007_002", "油断大敵です");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (1000, 3, "弱音を吐くなっ", 4, "vo_minigame_1013_icon_2_007_003", 10, 1, 5, "vo_minigame_1013_icon_1_007_003", "忌々しいっ…");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (1500, 4, "マコト班集合！", 3, "vo_minigame_1013_icon_2_008_001", 11, 99, 6, "vo_minigame_1013_icon_1_008_001", "大所帯ですわね");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (1500, 4, "連携してくぞ！", 3, "vo_minigame_1013_icon_2_008_002", 12, 99, 6, "vo_minigame_1013_icon_1_008_002", "エリコ班へようこそ");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (3000, 1, "みんなに力を！", 6, "vo_minigame_1013_icon_2_020_001", 13, 0, 8, "vo_minigame_1013_icon_1_020_001", "ナナカちゃんに\nお任せあれ");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (3000, 1, "任せてくれたまえ", 7, "vo_minigame_1013_icon_2_022_001", 14, 0, 9, "vo_minigame_1013_icon_1_022_001", "はっはっは！\n任せろ！");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (3000, 1, "ほな、いきまひょか", 8, "vo_minigame_1013_icon_2_023_001", 15, 0, 10, "vo_minigame_1013_icon_1_023_001", "どんどんいくわよ");
